/**
 * Run-JSON reading + validation (CLI-11, 2026-08-06 audit).
 *
 * Run files are an input boundary just like qrels.jsonl and corpus.toml
 * — hand-edited, regenerated by older harness versions, or copied
 * between machines — yet `report`/`compare` used to `as`-cast
 * `JSON.parse` straight to `RunResultJson` while every other input got
 * line-numbered validation. A missing metric then surfaced as `NaN` (or
 * a silent `?? 0` in the compare table) instead of a pointed error.
 * Same hand-rolled strategy as `validateQrel`: small enough not to need
 * zod, strict enough to catch drift early.
 */

import { readFileSync } from "node:fs";
import { errorMessage } from "./errors.js";
import { VALID_QUERY_TYPES } from "./qrels.js";
import type { MetricSummary, PerQueryMetrics, QueryType, RunResultJson } from "./types.js";
import { METRIC_KEYS, queryId } from "./types.js";

export class RunJsonLoadError extends Error {}

/** Read + parse + validate a run JSON file. `source` labels errors. */
export function readRun(path: string): RunResultJson {
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(path, "utf-8")) as unknown;
  } catch (err) {
    throw new RunJsonLoadError(`${path}: invalid run JSON: ${errorMessage(err)}`);
  }
  return validateRunJson(parsed, path);
}

const STRING_FIELDS = [
  "runId",
  "goldenSet",
  "corpusSha",
  "loctxSha",
  "embedder",
  "runtime",
  "chunkingConfig",
  "retrievalConfig",
  "chunkBoundaryHash",
  "startedAt",
  "finishedAt",
] as const;

export function validateRunJson(raw: unknown, source: string): RunResultJson {
  const root = requireObject(raw, "(root)", source);
  const strings = Object.fromEntries(
    STRING_FIELDS.map((f) => [f, requireString(root[f], f, source)]),
  ) as Record<(typeof STRING_FIELDS)[number], string>;

  const metricsRaw = requireObject(root["metrics"], "metrics", source);
  const overall = validateMetricSummary(metricsRaw["overall"], "metrics.overall", source);
  const byTypeRaw = requireObject(metricsRaw["byQueryType"], "metrics.byQueryType", source);
  const byQueryType: Record<string, MetricSummary> = {};
  for (const [type, value] of Object.entries(byTypeRaw)) {
    byQueryType[type] = validateMetricSummary(value, `metrics.byQueryType.${type}`, source);
  }

  const perQueryRaw = root["perQuery"];
  if (!Array.isArray(perQueryRaw)) {
    throw new RunJsonLoadError(`${source}: field 'perQuery' must be an array.`);
  }
  const perQuery = perQueryRaw.map((row, i) => validatePerQuery(row, i, source));

  return Object.freeze({
    ...strings,
    metrics: Object.freeze({ overall, byQueryType: Object.freeze(byQueryType) }),
    perQuery: Object.freeze(perQuery),
  });
}

function validatePerQuery(raw: unknown, index: number, source: string): PerQueryMetrics {
  const field = `perQuery[${index}]`;
  const row = requireObject(raw, field, source);
  const id = requireString(row["queryId"], `${field}.queryId`, source);
  const qt = requireString(row["queryType"], `${field}.queryType`, source);
  if (!VALID_QUERY_TYPES.has(qt as QueryType)) {
    throw new RunJsonLoadError(
      `${source}: ${field}.queryType must be one of ${[...VALID_QUERY_TYPES].join(", ")} (got '${qt}').`,
    );
  }
  return Object.freeze({
    queryId: queryId(id),
    queryType: qt as QueryType,
    ...validateMetricSummary(raw, field, source),
  });
}

function validateMetricSummary(raw: unknown, field: string, source: string): MetricSummary {
  const obj = requireObject(raw, field, source);
  const entries = METRIC_KEYS.map((key) => {
    const v = obj[key];
    if (typeof v !== "number" || Number.isNaN(v)) {
      throw new RunJsonLoadError(`${source}: field '${field}.${key}' must be a number.`);
    }
    return [key, v] as const;
  });
  // Object.fromEntries widens to a string index; the keys are exactly
  // METRIC_KEYS, so the assertion restores what the compiler dropped.
  return Object.freeze(Object.fromEntries(entries) as Record<(typeof METRIC_KEYS)[number], number>);
}

function requireObject(v: unknown, field: string, source: string): Record<string, unknown> {
  if (v === null || typeof v !== "object" || Array.isArray(v)) {
    throw new RunJsonLoadError(`${source}: field '${field}' must be a JSON object.`);
  }
  return v as Record<string, unknown>;
}

function requireString(v: unknown, field: string, source: string): string {
  if (typeof v !== "string") {
    throw new RunJsonLoadError(`${source}: field '${field}' must be a string.`);
  }
  return v;
}
